question.template:
""" Protótipo UniCV: pergunta de fluxograma. O estudante constrói um fluxograma com os blocos do Flowgorithm (Entrada, Saída, Atribuição, Se, Enquanto, Para e Fazer) e o corretor executa-o com os dados de cada caso de teste, comparando o que o fluxograma escreve com a saída esperada.
Parâmetros do modelo (todos opcionais; só se aceitam estes nomes, em inglês): max_steps número máximo de blocos executados por teste (por omissão 10000) require lista de tipos de bloco que o fluxograma tem de usar, de entre "input", "output", "assign", "if", "while", "for", "do" e "loop" (qualquer um dos três ciclos) forbid lista de tipos de bloco que o fluxograma não pode usar lang língua da pergunta: "pt" (por omissão), "en" ou "es". Define como se escrevem os valores lógicos (Verdadeiro/Falso, True/False, Verdadero/Falso) e a língua das mensagens quando o estudante não escolheu outra no editor. """ import ast import json import math import re import sys
__answer__ = """{{ STUDENT_ANSWER | e('py') }}""" __params__ = json.loads("""{{ QUESTION.parameters | json_encode | e('py') }}""") if not isinstance(__params__, dict): # Twig dá [] quando não há parâmetros. __params__ = {} # Os nomes dos parâmetros e dos tipos de figura são em inglês. PARAMETROS = ('require', 'forbid', 'max_steps', 'lang')
TIPOS = {'input': 'entrada', 'output': 'saida', 'process': 'atribuicao', 'if': 'se', 'while': 'enquanto', 'for': 'para', 'do': 'fazer', 'io': 'entrada_saida'} # Nomes de tipos aceites nos parâmetros 'exigir' e 'proibir', além dos de cima. GRUPOS = {'ciclo': {'enquanto', 'para', 'fazer'}, 'decisao': {'se'}, 'processo': {'atribuicao'}, 'entrada_saida': {'entrada', 'saida', 'entrada_saida'}} # Os tipos de figura dos parâmetros 'require' e 'forbid' (em inglês). OUTROS_NOMES = {'input': 'entrada', 'output': 'saida', 'assign': 'atribuicao', 'if': 'se', 'while': 'enquanto', 'for': 'para', 'do': 'fazer', 'loop': 'ciclo'}
NOMES = {'input': 'entrada', 'output': 'saida', 'assign': 'atribuicao', 'if': 'se', 'while': 'enquanto', 'for': 'para', 'do': 'fazer', 'loop': 'ciclo', 'salida': 'saida', 'asignacion': 'atribuicao', 'si': 'se', 'mientras': 'enquanto', 'hacer': 'fazer', 'bucle': 'ciclo'}
NOMES = { 'pt': {'entrada': 'Entrada', 'saida': 'Saída', 'atribuicao': 'Atribuição', 'se': 'Se', 'enquanto': 'Enquanto', 'para': 'Para', 'fazer': 'Fazer', 'entrada_saida': 'Entrada/Saída', 'ciclo': 'de ciclo (Enquanto, Para ou Fazer)', 'decisao': 'Se', 'processo': 'Atribuição'}, 'en': {'entrada': 'Input', 'saida': 'Output', 'atribuicao': 'Assign', 'se': 'If', 'enquanto': 'While', 'para': 'For', 'fazer': 'Do', 'entrada_saida': 'Input/Output', 'ciclo': 'loop (While, For or Do)', 'decisao': 'If', 'processo': 'Assign'}, 'es': {'entrada': 'Entrada', 'saida': 'Salida', 'atribuicao': 'Asignación', 'se': 'Si', 'enquanto': 'Mientras', 'para': 'Para', 'fazer': 'Hacer', 'entrada_saida': 'Entrada/Salida', 'ciclo': 'de ciclo (Mientras, Para o Hacer)', 'decisao': 'Si', 'processo': 'Asignación'}, } LOGICOS = {'pt': ('Verdadeiro', 'Falso'), 'en': ('True', 'False'), 'es': ('Verdadero', 'Falso')}
# As mensagens para o estudante, em cada língua. Para acrescentar uma língua # basta acrescentar aqui (e em NOMES e LOGICOS) uma entrada com as mesmas chaves. MENSAGENS = { 'pt': { 'em': "{onde}: {erro}.", 'figura': "Figura {nome} «{texto}»", 'figura_vazia': "Figura {nome} vazia", 'simbolo': "símbolo não reconhecido: '{s}'", 'falta_expressao': "falta uma expressão", 'seta': "a seta ← só pode ser usada numa atribuição", 'mal_escrita': "expressão mal escrita", 'nao_permitida': "expressão não permitida", 'funcao': "função não reconhecida", 'sem_valor': "a variável '{n}' é usada antes de ter um valor", 'divisao_zero': "divisão por zero", 'tipos': "operação entre valores de tipos incompatíveis (por exemplo, texto e número)", 'impossivel': "operação impossível com estes valores", 'reservada': "'{n}' é uma palavra reservada e não pode ser o nome de uma variável", 'lista_nomes': "devem vir aqui nomes de variáveis, separados por vírgulas", 'falta_nome': "falta o nome da variável", 'nome_funcao': "'{n}' é o nome de uma função e não pode ser uma variável", 'sem_conteudo': "a figura não tem conteúdo", 'io_antigo': "uma figura de Entrada/Saída começa por Ler ou por Escrever", 'forma_atribuicao': "uma figura de Atribuição tem a forma variável = expressão", 'forma_para': "uma figura Para tem a forma variável = início até fim (e, se quiser, passo p)", 'mais_dados': "o fluxograma pede mais dados do que os que existem neste teste", 'passo_zero': "o passo de uma figura Para tem de ser um número diferente de zero", 'tipo_desconhecido': "O fluxograma tem uma figura de tipo desconhecido.", 'nao_termina': "O fluxograma não termina: verifique se a condição do ciclo chega a ser falsa.", 'ilegivel': "Não foi possível ler o fluxograma.", 'vazio': "O fluxograma está vazio: acrescente figuras entre o Início e o Fim.", 'exigir': "O fluxograma deve usar pelo menos uma figura {nome}.", 'proibir': "Neste exercício o fluxograma não pode usar figuras {nome}.", 'parametro': "Erro na pergunta: o parâmetro do modelo «{p}» não existe (os parâmetros são require, forbid, max_steps, lang). Avise o docente.", 'valor': "Erro na pergunta: «{v}» não é um valor válido no parâmetro {p} (use input, output, assign, if, while, for, do, loop). Avise o docente.", }, 'en': { 'em': "{onde}: {erro}.", 'figura': "{nome} shape «{texto}»", 'figura_vazia': "Empty {nome} shape", 'simbolo': "unrecognised symbol: '{s}'", 'falta_expressao': "an expression is missing", 'seta': "the arrow ← can only be used in an assignment", 'mal_escrita': "badly written expression", 'nao_permitida': "expression not allowed", 'funcao': "unknown function", 'sem_valor': "the variable '{n}' is used before it has a value", 'divisao_zero': "division by zero", 'tipos': "operation between values of incompatible types (for example, text and number)", 'impossivel': "operation impossible with these values", 'reservada': "'{n}' is a reserved word and cannot be the name of a variable", 'lista_nomes': "variable names, separated by commas, are expected here", 'falta_nome': "the name of the variable is missing", 'nome_funcao': "'{n}' is the name of a function and cannot be a variable", 'sem_conteudo': "the shape has no content", 'io_antigo': "an Input/Output shape starts with Input or Output", 'forma_atribuicao': "an Assign shape has the form variable = expression", 'forma_para': "a For shape has the form variable = start to end (and, if you wish, step s)", 'mais_dados': "the flowchart asks for more data than this test has", 'passo_zero': "the step of a For shape must be a number other than zero", 'tipo_desconhecido': "The flowchart has a shape of an unknown type.", 'nao_termina': "The flowchart does not end: check that the loop condition eventually becomes false.", 'ilegivel': "The flowchart could not be read.", 'vazio': "The flowchart is empty: add shapes between Start and End.", 'exigir': "The flowchart must use at least one {nome} shape.", 'proibir': "In this exercise the flowchart cannot use {nome} shapes.", 'parametro': "Question error: there is no template parameter '{p}' (the parameters are require, forbid, max_steps, lang). Please tell your teacher.", 'valor': "Question error: '{v}' is not a valid value for the parameter {p} (use input, output, assign, if, while, for, do, loop). Please tell your teacher.", }, 'es': { 'em': "{onde}: {erro}.", 'figura': "Figura {nome} «{texto}»", 'figura_vazia': "Figura {nome} vacía", 'simbolo': "símbolo no reconocido: '{s}'", 'falta_expressao': "falta una expresión", 'seta': "la flecha ← solo se puede usar en una asignación", 'mal_escrita': "expresión mal escrita", 'nao_permitida': "expresión no permitida", 'funcao': "función no reconocida", 'sem_valor': "la variable '{n}' se usa antes de tener un valor", 'divisao_zero': "división por cero", 'tipos': "operación entre valores de tipos incompatibles (por ejemplo, texto y número)", 'impossivel': "operación imposible con estos valores", 'reservada': "'{n}' es una palabra reservada y no puede ser el nombre de una variable", 'lista_nomes': "aquí deben ir nombres de variables, separados por comas", 'falta_nome': "falta el nombre de la variable", 'nome_funcao': "'{n}' es el nombre de una función y no puede ser una variable", 'sem_conteudo': "la figura no tiene contenido", 'io_antigo': "una figura de Entrada/Salida empieza por Leer o por Escribir", 'forma_atribuicao': "una figura de Asignación tiene la forma variable = expresión", 'forma_para': "una figura Para tiene la forma variable = inicio hasta fin (y, si quiere, paso p)", 'mais_dados': "el diagrama pide más datos de los que hay en esta prueba", 'passo_zero': "el paso de una figura Para tiene que ser un número distinto de cero", 'tipo_desconhecido': "El diagrama tiene una figura de tipo desconocido.", 'nao_termina': "El diagrama no termina: compruebe que la condición del ciclo llega a ser falsa.", 'ilegivel': "No se pudo leer el diagrama de flujo.", 'vazio': "El diagrama está vacío: añada figuras entre Inicio y Fin.", 'exigir': "El diagrama debe usar al menos una figura {nome}.", 'proibir': "En este ejercicio el diagrama no puede usar figuras {nome}.", 'parametro': "Error en la pregunta: el parámetro de plantilla «{p}» no existe (los parámetros son require, forbid, max_steps, lang). Avise al docente.", 'valor': "Error en la pregunta: «{v}» no es un valor válido en el parámetro {p} (use input, output, assign, if, while, for, do, loop). Avise al docente.", }, }
# A língua da pergunta (parâmetro 'lang') e a das mensagens, que passa a ser a # que o estudante escolheu no editor quando a resposta a indica. LINGUA_PERGUNTA = __params__.get('lang') if __params__.get('lang') in MENSAGENS else 'pt' LINGUA = LINGUA_PERGUNTA
class ErroFluxograma(Exception): """Um erro a mostrar ao estudante: a chave da mensagem e os seus dados. As mensagens 'localizadas' já dizem em que figura está o erro. """
def __init__(self, chave, localizada=False, **dados): super().__init__(MENSAGENS[LINGUA][chave].format(**dados)) self.localizada = localizada
def em_figura(bloco, erro): """O mesmo erro, com a indicação da figura em que aconteceu.""" return ErroFluxograma('em', True, onde=bloco.descricao(), erro=str(erro))
# Palavras com significado próprio nas expressões: as comuns a todas as # línguas e as de cada língua. PALAVRAS = { 'and': 'and', 'or': 'or', 'not': 'not', 'mod': '%', 'div': '//', 'true': 'True', 'false': 'False', } PALAVRAS_DA_LINGUA = { 'pt': {'e': 'and', 'ou': 'or', 'não': 'not', 'nao': 'not', 'verdadeiro': 'True', 'falso': 'False'}, 'en': {}, 'es': {'verdadero': 'True', 'falso': 'False'}, } # A palavra com que o estudante pode começar o texto de uma figura (e que se ignora). INICIAIS = {'pt': {'if': 'se', 'while': 'enquanto', 'for': 'para', 'do': 'enquanto'}, 'en': {'if': 'if', 'while': 'while', 'for': 'for', 'do': 'while'}, 'es': {'if': 'si', 'while': 'mientras', 'for': 'para', 'do': 'mientras'}} SIMBOLOS = {'≤': '<=', '≥': '>=', '≠': '!=', '<>': '!=', '^': '**', '×': '*', '÷': '/', '&&': 'and', '||': 'or', '!': 'not'} # Palavras que separam as partes de uma figura Para: i = 1 até 10 passo 2 ATE = ('até', 'ate', 'to', 'hasta') PASSO = ('passo', 'step', 'paso')
TOKEN = re.compile(r''' (?P<texto>"[^"]*"|'[^']*') | (?P<numero>\d+(?:\.\d+)?) | (?P<nome>[^\W\d]\w*) | (?P<op><>|<=|>=|==|!=|\*\*|//|&&|\|\||[-+*/%<>=(),^≤≥≠×÷←&!]) | (?P<espaco>\s+) | (?P<outro>.) ''', re.VERBOSE)
NOS_PERMITIDOS = ( ast.Expression, ast.BinOp, ast.UnaryOp, ast.BoolOp, ast.Compare, ast.Name, ast.Load, ast.Constant, ast.Call, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow, ast.BitAnd, ast.USub, ast.UAdd, ast.Not, ast.And, ast.Or, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, )
def raiz(x): return math.sqrt(x)
def formatar(valor): """O texto com que um valor é escrito.""" if isinstance(valor, bool): return LOGICOS[LINGUA_PERGUNTA][0 if valor else 1] if isinstance(valor, float): return format(valor, '.10g') return str(valor)
def juntar(a, b): """O operador & do Flowgorithm: junta dois valores num texto.""" return formatar(a) + formatar(b)
# As funções que se podem usar nas expressões (os nomes não distinguem # maiúsculas de minúsculas, como no Flowgorithm). FUNCOES = { 'abs': abs, 'int': int, 'float': float, 'round': round, 'arred': round, 'raiz': raiz, 'sqrt': raiz, 'max': max, 'min': min, 'len': len, 'tamanho': len, 'tointeger': int, 'toreal': float, 'tostring': formatar, 'texto': formatar, '__juntar__': juntar, }
class TrocarJuncao(ast.NodeTransformer): """Troca a & b por __juntar__(a, b)."""
def visit_BinOp(self, no): self.generic_visit(no) if isinstance(no.op, ast.BitAnd): return ast.Call(func=ast.Name(id='__juntar__', ctx=ast.Load()), args=[no.left, no.right], keywords=[]) return no
def palavras(): """As palavras reservadas, na língua em que o estudante está a trabalhar.""" return dict(PALAVRAS, **PALAVRAS_DA_LINGUA[LINGUA])
def tokens(texto): """Lista de (tipo, valor) do texto de um bloco, sem os espaços.""" resultado = [] for m in TOKEN.finditer(texto): tipo = m.lastgroup if tipo == 'espaco': continue if tipo == 'outro': raise ErroFluxograma('simbolo', s=m.group()) resultado.append((tipo, m.group())) return resultado
def separar(toks, separador): """Divide a lista de tokens nos separadores que estão fora de parênteses.""" partes, atual, nivel = [], [], 0 for tipo, valor in toks: if tipo == 'op' and valor == '(': nivel += 1 elif tipo == 'op' and valor == ')': nivel -= 1 if tipo == 'op' and valor == separador and nivel == 0: partes.append(atual) atual = [] else: atual.append((tipo, valor)) partes.append(atual) return partes
def compilar(toks): """Converte os tokens de uma expressão em pseudocódigo numa expressão Python já verificada (só operações aritméticas, lógicas e de comparação). """ if not toks: raise ErroFluxograma('falta_expressao') partes = [] reservadas = palavras() for tipo, valor in toks: if tipo == 'nome': minusculas = valor.lower() if minusculas in reservadas: partes.append(reservadas[minusculas]) elif minusculas in FUNCOES: partes.append(minusculas) else: partes.append(valor) elif tipo == 'op': if valor == '=': partes.append('==') elif valor == '←': raise ErroFluxograma('seta') else: partes.append(SIMBOLOS.get(valor, valor)) else: partes.append(valor) fonte = ' '.join(partes) try: arvore = ast.parse(fonte, mode='eval') except SyntaxError: raise ErroFluxograma('mal_escrita') for no in ast.walk(arvore): if not isinstance(no, NOS_PERMITIDOS): raise ErroFluxograma('nao_permitida') if isinstance(no, ast.Call): if not isinstance(no.func, ast.Name) or no.func.id not in FUNCOES or no.keywords: raise ErroFluxograma('funcao') arvore = ast.fix_missing_locations(TrocarJuncao().visit(arvore)) return compile(arvore, '<fluxograma>', 'eval')
def avaliar(codigo, variaveis): """Calcula o valor de uma expressão compilada com as variáveis atuais.""" for nome in codigo.co_names: if nome not in variaveis and nome not in FUNCOES: raise ErroFluxograma('sem_valor', n=nome) ambiente = dict(FUNCOES) ambiente.update(variaveis) try: return eval(codigo, {'__builtins__': {}}, ambiente) except ZeroDivisionError: raise ErroFluxograma('divisao_zero') except TypeError: raise ErroFluxograma('tipos') except (ValueError, OverflowError): raise ErroFluxograma('impossivel')
def converter(texto): """Converte um dado lido em inteiro, real ou texto, conforme o que parecer.""" texto = texto.strip() if re.fullmatch(r'[-+]?\d+', texto): return int(texto) if re.fullmatch(r'[-+]?\d*[.,]\d+|[-+]?\d+[.,]\d*', texto): return float(texto.replace(',', '.')) return texto
def nomes_de_variaveis(toks): """Os nomes de uma lista de variáveis separadas por vírgulas.""" nomes = [] for parte in separar(toks, ','): if len(parte) == 1 and parte[0][0] == 'nome' and parte[0][1].lower() in palavras(): raise ErroFluxograma('reservada', n=parte[0][1]) if len(parte) != 1 or parte[0][0] != 'nome': raise ErroFluxograma('lista_nomes') nomes.append(parte[0][1]) return nomes
def verificar_nome(tok): """Garante que o token pode ser o nome de uma variável.""" if tok[0] != 'nome': raise ErroFluxograma('falta_nome') if tok[1].lower() in palavras(): raise ErroFluxograma('reservada', n=tok[1]) if tok[1].lower() in FUNCOES: raise ErroFluxograma('nome_funcao', n=tok[1]) return tok[1]
class Bloco: """Um bloco do fluxograma, já analisado."""
def __init__(self, no): self.tipo = no.get('type') self.texto = (no.get('text') or '').strip() if self.tipo not in TIPOS: raise ErroFluxograma('tipo_desconhecido', True) self.sim = [Bloco(n) for n in no.get('yes', [])] if self.tipo == 'if' else [] self.nao = [Bloco(n) for n in no.get('no', [])] if self.tipo == 'if' else [] self.corpo = [Bloco(n) for n in no.get('body', [])] if self.tipo in ('while', 'for', 'do') else [] try: self.analisar() except ErroFluxograma as erro: raise em_figura(self, erro)
def descricao(self): nome = NOMES[LINGUA][TIPOS[self.tipo]] modelo = MENSAGENS[LINGUA]['figura' if self.texto else 'figura_vazia'] return modelo.format(nome=nome, texto=self.texto)
def analisar(self): if not self.texto: raise ErroFluxograma('sem_conteudo') toks = tokens(self.texto) if self.tipo == 'io': # Formato antigo: um só bloco, com Ler ou Escrever no texto. palavra = toks[0][1].lower() if toks[0][0] == 'nome' else '' if palavra in ('ler', 'leia', 'leer', 'input', 'read'): self.tipo, toks = 'input', toks[1:] elif palavra in ('escrever', 'escreva', 'mostrar', 'escribir', 'output', 'print', 'write'): self.tipo, toks = 'output', toks[1:] else: raise ErroFluxograma('io_antigo') if self.tipo == 'input': self.nomes = nomes_de_variaveis(toks) elif self.tipo == 'output': self.expressoes = [compilar(parte) for parte in separar(toks, ',')] elif self.tipo == 'process': if len(toks) < 3 or toks[1] not in (('op', '='), ('op', '←')): raise ErroFluxograma('forma_atribuicao') self.nome = verificar_nome(toks[0]) self.expressao = compilar(toks[2:]) elif self.tipo == 'for': # variável = início até fim [passo p] toks = self.sem_inicial(toks) minusculas = [valor.lower() if tipo == 'nome' else None for tipo, valor in toks] ate = next((i for i, palavra in enumerate(minusculas) if palavra in ATE and i > 2), None) if ate is None: # Também se aceita i = 1 a 10 ate = next((i for i, palavra in enumerate(minusculas) if palavra == 'a' and i > 2), None) if len(toks) < 5 or toks[1] not in (('op', '='), ('op', '←')) or ate is None: raise ErroFluxograma('forma_para') passo = next((i for i, palavra in enumerate(minusculas) if palavra in PASSO and i > ate), None) self.nome = verificar_nome(toks[0]) self.inicio = compilar(toks[2:ate]) self.fim = compilar(toks[ate + 1:passo] if passo is not None else toks[ate + 1:]) self.passo = compilar(toks[passo + 1:]) if passo is not None else None else: self.condicao = compilar(self.sem_inicial(toks))
def sem_inicial(self, toks): """Os tokens sem a palavra do tipo da figura (Se, Enquanto, Para), quando o estudante a escreveu no início do texto. """ if len(toks) > 1 and toks[0][0] == 'nome' and toks[0][1].lower() == INICIAIS[LINGUA][self.tipo] \ and (toks[1][0] != 'op' or toks[1][1] in ('(', '!', '-')): return toks[1:] return toks
class Maquina: """Executa um fluxograma com os dados dados, guardando o que ele escreve."""
def __init__(self, dados, max_passos): self.dados = dados self.proximo = 0 self.variaveis = {} self.passos = 0 self.max_passos = max_passos
def passo(self): self.passos += 1 if self.passos > self.max_passos: raise ErroFluxograma('nao_termina', True)
def executar(self, blocos): for bloco in blocos: self.passo() try: self.executar_bloco(bloco) except ErroFluxograma as erro: if erro.localizada: raise raise em_figura(bloco, erro)
def executar_bloco(self, bloco): if bloco.tipo == 'input': for nome in bloco.nomes: if self.proximo >= len(self.dados): raise ErroFluxograma('mais_dados') self.variaveis[nome] = converter(self.dados[self.proximo]) self.proximo += 1 elif bloco.tipo == 'output': print(' '.join(formatar(avaliar(e, self.variaveis)) for e in bloco.expressoes)) elif bloco.tipo == 'process': self.variaveis[bloco.nome] = avaliar(bloco.expressao, self.variaveis) elif bloco.tipo == 'if': if avaliar(bloco.condicao, self.variaveis): self.executar(bloco.sim) else: self.executar(bloco.nao) elif bloco.tipo == 'while': while avaliar(bloco.condicao, self.variaveis): self.executar(bloco.corpo) self.passo() elif bloco.tipo == 'do': while True: self.executar(bloco.corpo) self.passo() if not avaliar(bloco.condicao, self.variaveis): break else: fim = avaliar(bloco.fim, self.variaveis) passo = avaliar(bloco.passo, self.variaveis) if bloco.passo is not None else 1 if isinstance(passo, bool) or not isinstance(passo, (int, float)) or passo == 0: raise ErroFluxograma('passo_zero') self.variaveis[bloco.nome] = avaliar(bloco.inicio, self.variaveis) while (self.variaveis[bloco.nome] <= fim) if passo > 0 else (self.variaveis[bloco.nome] >= fim): self.executar(bloco.corpo) self.passo() self.variaveis[bloco.nome] = self.variaveis[bloco.nome] + passo
def todos(blocos): """Todos os blocos do fluxograma, incluindo os que estão dentro de outros.""" for bloco in blocos: yield bloco yield from todos(bloco.sim) yield from todos(bloco.nao) yield from todos(bloco.corpo)
def carregar(resposta): """Os blocos do fluxograma da resposta (que vem em JSON).""" try: dados = json.loads(resposta) fluxograma = json.loads(dados['flowchart'][0]) if dados.get('flowchart', [''])[0] else {'nodes': []} nos = fluxograma['nodes'] if fluxograma.get('lang') in MENSAGENS: global LINGUA LINGUA = fluxograma['lang'] except (ValueError, KeyError, IndexError, TypeError, AttributeError): raise ErroFluxograma('ilegivel', True) if not nos: raise ErroFluxograma('vazio', True) return [Bloco(no) for no in nos]
def verificar_tipos(blocos, params): usados = {TIPOS[b.tipo] for b in todos(blocos)} nomes = NOMES[LINGUA] for chave, parametro, falha in (('exigir', 'require', lambda aceites: not (aceites & usados)), ('proibir', 'forbid', lambda aceites: bool(aceites & usados))): for tipo in params.get(parametro, []): tipo = OUTROS_NOMES[str(tipo).lower()] if falha(GRUPOS.get(tipo, {tipo})): raise ErroFluxograma(chave, True, nome=nomes[tipo])
def verificar_parametros(params): """Os nomes dos parâmetros e os tipos de figura têm de ser os previstos.""" for nome in params: if nome not in PARAMETROS and not str(nome).startswith('_'): raise ErroFluxograma('parametro', True, p=nome) for nome in ('require', 'forbid'): valores = params.get(nome, []) if not isinstance(valores, list): valores = [valores] params[nome] = valores for valor in valores: if str(valor).lower() not in OUTROS_NOMES: raise ErroFluxograma('valor', True, v=valor, p=nome)
try: verificar_parametros(__params__) __blocos__ = carregar(__answer__) verificar_tipos(__blocos__, __params__) Maquina(sys.stdin.read().splitlines(), int(__params__.get('max_steps', 10000))).executar(__blocos__) except ErroFluxograma as __erro__: print(f"*** {__erro__}")
